ALTER TABLE public.deliveries ADD COLUMN duration_minutes integer CHECK(duration_minutes BETWEEN 1 AND 10080), ADD COLUMN duration_basis text, ADD COLUMN duration_recorded_by uuid, ADD COLUMN duration_recorded_at timestamptz;
COMMENT ON COLUMN public.deliveries.duration_minutes IS 'Recorded planning commitment duration, supported by duration_basis; never inferred travel time.';
CREATE OR REPLACE FUNCTION public.delivery_duration_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF TG_OP='INSERT' THEN IF NEW.duration_minutes IS NOT NULL AND NOT public.is_trusted_writer() THEN RAISE EXCEPTION 'Only authorised duration recording is allowed'; END IF;
ELSIF NEW.duration_minutes IS DISTINCT FROM OLD.duration_minutes OR NEW.duration_basis IS DISTINCT FROM OLD.duration_basis OR NEW.duration_recorded_by IS DISTINCT FROM OLD.duration_recorded_by OR NEW.duration_recorded_at IS DISTINCT FROM OLD.duration_recorded_at THEN
IF coalesce(current_setting('zwits.duration_recording',true),'')<>'on' THEN RAISE EXCEPTION 'Use authorised duration recording'; END IF;
END IF;
IF NEW.duration_minutes IS NOT NULL THEN
IF length(trim(coalesce(NEW.duration_basis,'')))<5 OR NEW.duration_recorded_at IS NULL OR NEW.duration_recorded_by IS NULL THEN RAISE EXCEPTION 'Duration requires source and recording identity'; END IF;
IF NEW.scheduled_for IS NOT NULL AND (TG_OP='INSERT' OR NEW.scheduled_for IS DISTINCT FROM OLD.scheduled_for OR NEW.duration_minutes IS DISTINCT FROM OLD.duration_minutes) THEN NEW.scheduled_until:=NEW.scheduled_for+make_interval(mins=>NEW.duration_minutes); END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER aa_delivery_duration BEFORE INSERT OR UPDATE ON public.deliveries FOR EACH ROW EXECUTE FUNCTION public.delivery_duration_guard();
CREATE OR REPLACE FUNCTION public.admin_record_delivery_duration(_id uuid,_expected timestamptz,_minutes integer,_basis text,_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deliveries; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _minutes IS NULL OR _minutes NOT BETWEEN 1 AND 10080 OR length(trim(coalesce(_basis,''))) NOT BETWEEN 5 AND 1000 OR length(trim(coalesce(_reason,''))) NOT BETWEEN 5 AND 1000 THEN RAISE EXCEPTION 'Valid duration, source and reason required'; END IF;
SELECT * INTO d FROM public.deliveries WHERE id=_id FOR UPDATE; IF NOT FOUND OR d.updated_at IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'Job changed; refresh'; END IF;
IF d.status NOT IN ('pending','matching','offered') OR d.driver_id IS NOT NULL OR EXISTS(SELECT 1 FROM public.delivery_offers WHERE delivery_id=_id AND status='offered' AND expires_at>now()) OR public.dispatch_job_blocked('delivery',_id) THEN RAISE EXCEPTION 'Record duration before offering; assigned schedule changes require participant approval'; END IF;
PERFORM set_config('zwits.trusted','on',true); PERFORM set_config('zwits.duration_recording','on',true);
UPDATE public.deliveries SET duration_minutes=_minutes,duration_basis=trim(_basis),duration_recorded_by=auth.uid(),duration_recorded_at=now() WHERE id=_id;
INSERT INTO public.admin_job_actions(action_key,kind,job_id,actor,action,reason,before_values,after_values) VALUES(gen_random_uuid(),'delivery',_id,auth.uid(),'duration_recorded',trim(_reason),jsonb_build_object('minutes',d.duration_minutes,'basis',d.duration_basis),jsonb_build_object('minutes',_minutes,'basis',trim(_basis)));
PERFORM public.log_admin_action('duration_recorded','delivery',_id,jsonb_build_object('minutes',_minutes,'basis',trim(_basis),'reason',trim(_reason))); RETURN jsonb_build_object('ok',true); END $$;
CREATE OR REPLACE FUNCTION public.admin_dispatch_insights(_from timestamptz,_to timestamptz,_driver uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE calendar jsonb; custody jsonb; performance jsonb; payouts jsonb; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
IF _from IS NULL OR _to IS NULL OR _to<=_from OR _to-_from>interval '31 days' THEN RAISE EXCEPTION 'Choose up to 31 days'; END IF;
WITH jobs AS (SELECT d.id,d.driver_id,d.pickup_address,d.dropoff_address,d.scheduled_for,d.scheduled_until,d.status,d.duration_minutes,d.duration_basis,coalesce(dr.full_name,'Driver') name FROM public.deliveries d JOIN public.driver_profiles dr ON dr.user_id=d.driver_id WHERE (_driver IS NULL OR d.driver_id=_driver) AND d.scheduled_for<_to AND (coalesce(d.scheduled_until,'infinity')>_from) AND d.status NOT IN ('delivered','cancelled','failed') ORDER BY d.scheduled_for LIMIT 501)
SELECT coalesce(jsonb_agg(to_jsonb(j)||jsonb_build_object('conflicts',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',o.id,'start',o.scheduled_for,'end',o.scheduled_until,'reason',CASE WHEN o.scheduled_for IS NULL OR o.scheduled_until IS NULL OR j.scheduled_until IS NULL THEN 'Timing incomplete; overlap cannot be ruled out' ELSE 'Overlapping commitments' END)),'[]') FROM public.deliveries o WHERE o.id<>j.id AND o.driver_id=j.driver_id AND o.status IN ('accepted','arriving','picked_up','pending','matching','offered') AND (o.scheduled_for IS NULL OR (o.scheduled_for<coalesce(j.scheduled_until,'infinity') AND coalesce(o.scheduled_until,'infinity')>j.scheduled_for))))),'[]') INTO calendar FROM jobs j;
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO custody FROM (SELECT d.id,d.status,d.pickup_address,d.dropoff_address,d.picked_up_at,d.delivered_at,CASE WHEN d.status='delivered' THEN 'delivered' WHEN d.status='picked_up' AND r.status='awaiting_handover' THEN 'handover_pending' WHEN d.status='picked_up' THEN 'in_transit' WHEN d.picked_up_at IS NOT NULL THEN 'custody_requires_review' ELSE 'awaiting_collection' END custody_status,CASE WHEN d.picked_up_at IS NOT NULL AND d.status<>'delivered' THEN d.driver_id ELSE NULL END custodian_id,CASE WHEN d.picked_up_at IS NOT NULL AND d.status<>'delivered' THEN dr.full_name ELSE NULL END custodian_name,r.replacement_driver,rr.full_name replacement_name,r.previous_ack_at,r.replacement_ack_at,r.handover_at,r.handover_location FROM public.deliveries d LEFT JOIN public.driver_profiles dr ON dr.user_id=d.driver_id LEFT JOIN LATERAL(SELECT * FROM public.delivery_reassignments WHERE delivery_id=d.id ORDER BY created_at DESC LIMIT 1)r ON true LEFT JOIN public.driver_profiles rr ON rr.user_id=r.replacement_driver WHERE (_driver IS NULL OR d.driver_id=_driver) AND (d.status='picked_up' OR r.status IN ('awaiting_replacement','awaiting_handover') OR (d.picked_up_at IS NOT NULL AND d.status<>'delivered')) ORDER BY d.updated_at DESC LIMIT 100)x;
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO performance FROM (SELECT p.user_id,p.full_name,p.available,p.verification_status,(SELECT count(*) FROM public.deliveries d WHERE d.driver_id=p.user_id AND d.status IN ('accepted','arriving','picked_up')) active_jobs,count(d.id) FILTER(WHERE d.status='delivered') delivered,count(d.id) FILTER(WHERE d.status='cancelled') cancellations,count(d.id) FILTER(WHERE d.status='delivered' AND d.delivered_at IS NOT NULL AND d.scheduled_until IS NOT NULL) timed_deliveries,count(d.id) FILTER(WHERE d.status='delivered' AND d.delivered_at<=d.scheduled_until) on_time,count(d.id) FILTER(WHERE d.status='delivered' AND d.delivered_at>d.scheduled_until) late,count(d.id) FILTER(WHERE d.status='delivered' AND (d.scheduled_until IS NULL OR d.delivered_at IS NULL)) timing_unknown FROM public.driver_profiles p LEFT JOIN public.deliveries d ON d.driver_id=p.user_id AND d.created_at>=_from AND d.created_at<_to WHERE _driver IS NULL OR p.user_id=_driver GROUP BY p.user_id,p.full_name,p.available,p.verification_status ORDER BY p.full_name LIMIT 200)x;
SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') INTO payouts FROM (SELECT w.id,w.provider_user_id,p.full_name,w.amount,w.method,w.status,w.created_at,w.processed_at,w.failure_reason FROM public.provider_withdrawals w JOIN public.driver_profiles p ON p.user_id=w.provider_user_id WHERE (_driver IS NULL OR w.provider_user_id=_driver) AND w.created_at>=_from AND w.created_at<_to ORDER BY w.created_at DESC LIMIT 100)x;
RETURN jsonb_build_object('calendar',calendar,'calendar_truncated',jsonb_array_length(calendar)>500,'custody',custody,'performance',performance,'payouts',payouts,'as_of',now()); END $$;
CREATE OR REPLACE FUNCTION public.admin_delivery_alternatives(_id uuid,_assignee uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d public.deliveries; p public.driver_profiles; candidate timestamptz; finish timestamptz; c jsonb; result jsonb:='[]'; BEGIN
IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF;
SELECT * INTO d FROM public.deliveries WHERE id=_id; SELECT * INTO p FROM public.driver_profiles WHERE user_id=_assignee;
IF d.duration_minutes IS NULL OR d.duration_basis IS NULL THEN RETURN jsonb_build_object('slots',result,'limitation','Record a supported duration before suggesting times'); END IF;
IF p.work_start IS NULL OR p.work_end IS NULL OR p.work_start::time>=p.work_end::time THEN RETURN jsonb_build_object('slots',result,'limitation','Declare reliable same-day driver working hours before suggesting times'); END IF;
FOR candidate IN SELECT t FROM generate_series(greatest(now(),coalesce(d.scheduled_for,now())),greatest(now(),coalesce(d.scheduled_for,now()))+interval '7 days',interval '30 minutes')t LOOP
finish:=candidate+make_interval(mins=>d.duration_minutes);
c:=public.dispatch_assignment_check('delivery',_id,_assignee,candidate,finish);
IF (c->>'ok')::boolean THEN result:=result||jsonb_build_array(jsonb_build_object('start',candidate,'end',finish)); EXIT WHEN jsonb_array_length(result)=3; END IF;
END LOOP;
RETURN jsonb_build_object('slots',result,'limitation','Checked against recorded commitments and declared hours; travel feasibility is not estimated. Recheck and obtain required approvals before scheduling.'); END $$;
REVOKE ALL ON FUNCTION public.admin_record_delivery_duration(uuid,timestamptz,integer,text,text),public.admin_dispatch_insights(timestamptz,timestamptz,uuid),public.admin_delivery_alternatives(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_record_delivery_duration(uuid,timestamptz,integer,text,text),public.admin_dispatch_insights(timestamptz,timestamptz,uuid),public.admin_delivery_alternatives(uuid,uuid) TO authenticated,service_role;